import os
import json

session_log = '/home/ubuntu/runs/paper/qwen-h0-u4-own/play/users/u000/system/state/sessions/01a18fec-04d2-706a-9e08-be7c49c088e3.jsonl'

with open(session_log) as fp:
    lines = fp.readlines()

print("Checking recent session log for task messages:\n")

task_found = False
for line in lines[-30:]:
    try:
        entry = json.loads(line)
        entry_type = entry.get('type', '')
        if entry_type in ['task', 'custom', 'custom_message'] or 'task' in entry:
            print(f"[{entry.get('timestamp', '')}] {entry_type}")
            if 'data' in entry and 'task' in entry['data']:
                print(f"  Task: {entry['data']['task']}")
                task_found = True
            elif 'message' in entry:
                content = entry['message'].get('content', '')
                if task_found:
                    continue
                if any(kw in content.lower() for kw in ['task', 'new', 'next', 'puzzle', 'grid']):
                    print(f"  Content snippet: {str(content)[:200]}")
    except:
        pass

if not task_found:
    print("\nNo task message found in recent logs.")

